function renderCases(run){$('cases-content').replaceChildren();if(!run.cases.length){empty('cases-content',run.kind==='project'?t('项目运行的 Agent 用例保存在子运行中。'):t('当前没有用例结果。'));for(const s of run.coverageSources||[])$('cases-content').append(button((s.checkId||'Agent')+t(' · 打开子运行 ↗'),()=>select(s.runId)))}for(const c of run.cases){const detail=document.createElement('details');detail.className='check-row';detail.dataset.checkId=c.caseId;detail.append(text('summary',(c.passed?'✓ ':'! ')+c.caseId+' · '+time(c.metrics?.latencyMs)));for(const a of c.assertions||[])detail.append(text('div',(a.passed?'✓ ':'! ')+(a.message||a.id||t('断言结果')),'assertion'+(a.passed?'':' bad')));if(c.metrics)detail.append(text('pre',JSON.stringify(c.metrics,null,2)));if(c.trajectoryId){const out=text('pre',t('点击后读取轨迹。'));const sourceRun=run.runId;detail.append(button(t('加载轨迹 / state diff'),async()=>{const value=await api('/api/runs/'+encodeURIComponent(sourceRun)+'/trajectory/'+encodeURIComponent(c.trajectoryId));out.textContent=JSON.stringify(value,null,2)}),out)}$('cases-content').append(detail)}$('timeline').replaceChildren(...run.timeline.map(e=>text('div',e.type+(e.at?' · '+e.at:''),'timeline-event')));if(!run.timeline.length)empty('timeline',t('项目检查的执行顺序与耗时见总览。'))}
function renderEvidence(run){$('evidence-content').replaceChildren();const fields=[[t('完整性'),(run.integrity?.status==='partial'?t('运行中 / 未封存'):labels[run.integrity?.status])||t('尚无封存记录')],[t('运行 ID'),run.runId],[t('来源运行'),run.retryOf||run.replayOf||t('独立运行')],[t('源码哈希'),run.evidence?.reproduction?.sourceHash||t('未记录')],[t('配置哈希'),run.evidence?.reproduction?.configHash||t('未记录')],[t('证据清单'),run.integrity?.manifestHash||t('未封存')]];for(const [name,value] of fields){const row=text('div',undefined,'evidence-line');row.append(text('span',name),text('strong',value));$('evidence-content').append(row)}$('evidence-content').append(text('p',t('历史列表只提供摘要；选中运行后校验证据。运行中的 artifact 尚未完成封存。'),'mini-note'));if(run.gate)$('evidence-content').append(text('pre',JSON.stringify(run.gate,null,2)));void renderRepairEvidence(run.runId)}
